class GpsFormController{constructor($scope,$timeout,$mdDialog,DispatchData,toastrService,NgMap,addressDetails,suburbOptions,title,submitLabel){this.$scope=$scope;this.$timeout=$timeout;this.$mdDialog=$mdDialog;this.DispatchData=DispatchData;this.toastrService=toastrService;this.NgMap=NgMap;this.title=title;this.addressDetails=addressDetails;this.suburbOptions=suburbOptions;this.submitLabel=submitLabel;this.ourSuburbSearchText="";this.addressSearchText="";this.ourSuburbSelectedItem=this.findSuburbByDistrict(addressDetails.suburb);$timeout(()=>{this.mapDisplay=true},500);NgMap.getMap().then(map=>{console.log("Loading Map!");this.map=map;this.marker=map.markers[0];this.addressSearchAutocomplete(addressDetails.address).then(_=>console.log("Address Search Complete!"))})}findSuburbByDistrict(district){let lowerCaseDistrict=district.toLowerCase();return this.suburbOptions.find(localSuburb=>localSuburb.text.toLowerCase()===lowerCaseDistrict||localSuburb.alias&&localSuburb.alias.toLowerCase()===lowerCaseDistrict)}transformSuggestions(data){return data.suggestions.map(obj=>({id:obj.locationId,text:obj.label.split(", ").reverse().join(", ")}))}ourSuburbSearch(query){return query?this.suburbOptions.filter(suburb=>suburb.text.toLowerCase().indexOf(query.toLowerCase())!==-1):this.suburbOptions}async addressSearchAutocomplete(searchText){try{const suggestions=await this.DispatchData.autocompleteAddressSearch(searchText);return this.transformSuggestions(suggestions)}catch(error){this.toastrService.showErrorToast(error.message)}}async addressSearchItemSelected(item){try{const data=await this.DispatchData.getGeoCodeInformation(item);const returnedLocation=data.Response.View[0].Result[0].Location;console.log("Suburb = "+returnedLocation.Address.District);console.log("PostCode = "+returnedLocation.Address.PostalCode);const mappedSub=this.findSuburbByDistrict(returnedLocation.Address.District);if(mappedSub!==undefined){console.log(mappedSub);this.ourSuburbSelectedItem=mappedSub}else{this.ourSuburbSelectedItem=null;this.toastrService.showWarningToast("Matching suburb could not be found from this address."+"Please select manually.")}this.addressDetails.filledAddress=returnedLocation.Address.Label;this.addressDetails.lat=returnedLocation.DisplayPosition.Latitude;this.addressDetails.long=returnedLocation.DisplayPosition.Longitude;this.addressDetails.address=returnedLocation.Address.Label;this.addressDetails.suburb=returnedLocation.Address.District;this.addressDetails.postCode=returnedLocation.Address.PostalCode;const latLng=new google.maps.LatLng(returnedLocation.DisplayPosition.Latitude,returnedLocation.DisplayPosition.Longitude);this.map.setCenter(latLng);this.marker.setPosition(latLng)}catch(error){console.log("Error: ",error)}}async submit(addressDetails){if(this.ourSuburbSelectedItem.id!==undefined){addressDetails.our_suburb=this.ourSuburbSelectedItem.id}if(addressDetails.our_suburb===undefined){const alert=this.$mdDialog.alert({title:"Courier Suburb Not Mapped",textContent:"You must pick one of our suburbs to map this address to",ok:"OK"});await this.$mdDialog.show(alert);return}this.$mdDialog.hide(addressDetails)}copyGpsAddress(address){this.addressSearchText=address}moveMarker(event){this.addressDetails.lat=event.latLng.lat();this.addressDetails.long=event.latLng.lng();this.$scope.$apply()}markerDragend(event){const location=event.latLng;try{this.DispatchData.retrieveAddresses(location.lat(),location.lng()).then(data=>{const returnedLocation=data.Response.View[0].Result[0].Location;this.addressDetails.address=returnedLocation.Address.Label;this.addressDetails.suburb=returnedLocation.Address.District;this.addressDetails.lat=returnedLocation.DisplayPosition.Latitude;this.addressDetails.long=returnedLocation.DisplayPosition.Longitude;console.log("Suburb = "+returnedLocation.Address.District);console.log("PostCode = "+returnedLocation.Address.PostalCode);const mappedSub=this.suburbOptions.find(obj=>obj.text===returnedLocation.Address.District||obj.alias===returnedLocation.Address.District);if(mappedSub!==undefined){console.log(mappedSub);this.ourSuburbSelectedItem=mappedSub}else{this.ourSuburbSelectedItem=null}})}catch(error){this.toastrService.showErrorToast(error.message)}}placeChanged(place){try{this.addressDetails.lat=place.geometry.location.lat();this.addressDetails.long=place.geometry.location.lng();if(place.address_components.find(x=>x.types[0]==="postal_code")){this.addressDetails.postCode=place.address_components.find(x=>x.types[0]==="postal_code").long_name}this.map.setCenter(place.geometry.location)}catch(error){this.toastrService.showErrorToast(error.message)}}cancel(){this.$mdDialog.cancel()}}